import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Fully static HTML/CSS/JS export — no Node.js server needed. Output: `out/`.
  output: "export",
  // Emit `/en/about/index.html` etc. so plain Apache/LiteSpeed/Nginx hosting
  // resolves every route (including a browser refresh) without rewrite rules.
  trailingSlash: true,
  turbopack: {
    // Pin the project root: a parent folder contains another package.json/lockfile.
    root: __dirname,
  },
  images: {
    // Responsive WebP variants are pre-generated by `npm run images` and rendered
    // by `components/ui/Media.tsx`, so the runtime image optimizer is never used.
    unoptimized: true,
  },
  experimental: {
    // One bilingual 404 page, because the app has two root layouts
    // (the language gate at `/` and the localized site under `/[locale]`).
    globalNotFound: true,
  },
  poweredByHeader: false,
};

export default nextConfig;
